#!/bin/bash
# Fix Gradle files generated by flutter create.
# Flutter 3.47.5 generates build.gradle files with readWithUTF8() which
# doesn't exist in Gradle's Groovy. Replace with proper Groovy syntax.
cd android

# Replace project-level build.gradle with simple Groovy
rm -f build.gradle.kts
cat > build.gradle << 'EOF'
allprojects {
    repositories {
        google()
        mavenCentral()
    }
}
EOF

# Replace app-level build.gradle with working Groovy (no readWithUTF8)
cat > app/build.gradle << 'GRADLE_EOF'
def localProperties = new Properties()
def localPropertiesFile = rootProject.file('local.properties')
if (localPropertiesFile.exists()) {
    localPropertiesFile.withReader('UTF-8') { reader ->
        localProperties.load(reader)
    }
}
def flutterRoot = localProperties.getProperty('flutter.sdk')
if (flutterRoot == null) {
    throw new GradleException("Flutter SDK not found. Define location with flutter.sdk in the local.properties file.")
}
def flutterVersionCode = localProperties.getProperty('flutterVersionCode') ?: '1'
def flutterVersionName = localProperties.getProperty('flutterVersionName') ?: '1.0.0'
apply plugin: 'com.android.application'
apply plugin: 'kotlin-android'
apply from: "$flutterRoot/packages/flutter_tools/gradle/flutter.gradle"
android {
    namespace = "com.helix.helix"
    compileSdkVersion flutter.compileSdkVersion
    ndkVersion flutter.ndkVersion
    compileOptions {
        sourceCompatibility JavaVersion.VERSION_1_8
        targetCompatibility JavaVersion.VERSION_1_8
    }
    kotlinOptions { jvmTarget = '1.8' }
    sourceSets { main.java.srcDirs += 'src/main/kotlin' }
    defaultConfig {
        applicationId "com.helix.helix"
        minSdkVersion flutter.minSdkVersion
        targetSdkVersion flutter.targetSdkVersion
        versionCode flutterVersionCode.toInteger()
        versionName flutterVersionName
    }
    buildTypes { release { signingConfig signingConfigs.debug } }
}
flutter { source '../..' }
dependencies {
    implementation "org.jetbrains.kotlin:kotlin-stdlib-jdk8:$kotlin_version"
    implementation "androidx.core:core-ktx:+"
    implementation "androidx.annotation:annotation:+"
    implementation "androidx.lifecycle:lifecycle-runtime-ktx:+"
    implementation "androidx.activity:activity:+"
}
GRADLE_EOF

echo "Gradle files fixed"
